import { Component, computed, input } from '@angular/core';
import { NzAvatarModule } from 'ng-zorro-antd/avatar';

/** Trạng thái hiện diện chấm góc avatar. online=xanh · away=vàng · busy=đỏ · offline=xám. */
export type HrmAvatarStatus = 'online' | 'offline' | 'busy' | 'away';

/** hrm-avatar — bọc nz-avatar. text | src | icon(ant). size = number | 'small'|'default'|'large'.
 *  colorful: tự chọn 1 trong 8 màu hue (token ramp) theo tên → mỗi người 1 màu ổn định, không trùng nhàm.
 *  colorSeed: chuỗi để băm ra màu (mặc định = text); truyền tên đầy đủ để đa dạng khi text chỉ là viết tắt.
 *  status: chấm hiện diện góc (online/offline/busy/away) + vòng viền nền — dùng cho ô người dùng trong bảng. */
@Component({
  selector: 'hrm-avatar',
  imports: [NzAvatarModule],
  template: `
    <nz-avatar
      [nzText]="text() || undefined"
      [nzSrc]="src() || undefined"
      [nzIcon]="icon() || undefined"
      [nzSize]="size()"
      [nzShape]="shape()"></nz-avatar>
    @if (status()) {
      <span class="av-status" [attr.data-status]="status()"></span>
    }
  `,
  host: {
    class: 'hrm-avatar',
    '[attr.data-hue]': 'hueIdx()',
    '[attr.data-status-pos]': 'status() ? statusPosition() : null',
  },
  styles: [`
:host { position: relative; display: inline-flex; vertical-align: middle; }

/* colorful: nền hue SOLID (-600) + chữ TRẮNG (token) — 8 màu từ ramp. */
:host([data-hue="0"]) ::ng-deep .ant-avatar { background: var(--blue-600); color: var(--static-white); }
:host([data-hue="1"]) ::ng-deep .ant-avatar { background: var(--green-600); color: var(--static-white); }
:host([data-hue="2"]) ::ng-deep .ant-avatar { background: var(--amber-600); color: var(--static-white); }
:host([data-hue="3"]) ::ng-deep .ant-avatar { background: var(--red-600); color: var(--static-white); }
:host([data-hue="4"]) ::ng-deep .ant-avatar { background: var(--purple-600); color: var(--static-white); }
:host([data-hue="5"]) ::ng-deep .ant-avatar { background: var(--teal-600); color: var(--static-white); }
:host([data-hue="6"]) ::ng-deep .ant-avatar { background: var(--cyan-600); color: var(--static-white); }
:host([data-hue="7"]) ::ng-deep .ant-avatar { background: var(--pink-600); color: var(--static-white); }

/* status: chấm hiện diện + vòng viền nền (tách avatar khỏi nền dưới). */
.av-status {
  position: absolute; right: 0; width: 28%; height: 28%;
  min-width: 8px; min-height: 8px; max-width: 14px; max-height: 14px;
  border-radius: var(--radius-full);
  box-shadow: 0 0 0 2px var(--bg-surface);
}
:host([data-status-pos='bottom']) .av-status { bottom: 4%; }
:host([data-status-pos='top']) .av-status { top: 4%; }
.av-status[data-status='online']  { background: var(--success-base); }
.av-status[data-status='offline'] { background: var(--neutral-400); }
.av-status[data-status='busy']    { background: var(--error-base); }
.av-status[data-status='away']    { background: var(--away-base); }
  `],
})
export class HrmAvatar {
  readonly text = input('');
  readonly src = input('');
  readonly icon = input('');
  readonly size = input<number | 'small' | 'default' | 'large'>('default');
  readonly shape = input<'circle' | 'square'>('circle');
  /** Tự tô 1 trong 8 màu hue theo tên (token ramp) thay vì màu mặc định. */
  readonly colorful = input(false);
  /** Chuỗi băm ra màu (mặc định dùng text). */
  readonly colorSeed = input('');
  /** Chấm hiện diện góc (online/offline/busy/away). null = không hiện. */
  readonly status = input<HrmAvatarStatus | null>(null);
  /** Vị trí chấm: 'bottom' (mặc định, góc phải-dưới) hoặc 'top' (góc phải-trên). */
  readonly statusPosition = input<'top' | 'bottom'>('bottom');

  /** Chỉ số hue 0..7, hoặc null khi không tô màu (giữ nền mặc định). */
  protected readonly hueIdx = computed<number | null>(() => {
    if (!this.colorful()) return null;
    const seed = this.colorSeed() || this.text();
    if (!seed) return null;
    let h = 0;
    for (let i = 0; i < seed.length; i++) h = (h + seed.charCodeAt(i)) % 8;
    return h;
  });
}
